const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M8 5l9 5"/>',chat:'<path d="M20 15a3 3 0 0 1-3 3H8l-5 3V6a3 3 0 0 1 3-3h11a3 3 0 0 1 3 3z"/><path d="M7 8h9M7 12h6"/>',storage:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',device:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M9 6h6M11 18h2"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',bell:'<path d="M5 16h14l-2-3V9a5 5 0 0 0-10 0v4zM10 20h4"/>',external:'<path d="M14 3h7v7M21 3 11 13M10 3H4v17h17v-6"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 4 3 2 3-1 3 3 3-2v-3l4-2-1-4-3-1-1-4z"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const agents=[{id:'notetaker',name:'Notetaker',maker:'AttentionAGI',category:'Productivity',description:'Be in the moment. Let your notes take themselves.',price:'Free',rating:'4.9',color:'#e8eddf',ink:'#788d5e',type:0,label:'LESS TYPING. MORE LIVING.'},{id:'thinker',name:'Thinker',maker:'AttentionAGI',category:'Everyday',description:'A little perspective for your next big idea.',price:'Free',rating:'4.9',color:'#ede9f2',ink:'#9a88b2',type:1,label:'MAKE ROOM FOR IDEAS.'},{id:'lingo',name:'Lingo',maker:'Lingua Labs',category:'Learning',description:'Find your words. In any language.',price:'$3 / mo',rating:'4.8',color:'#f1ede1',ink:'#ab9869',type:2,label:'THE WORLD, IN YOUR WORDS.'},{id:'focus',name:'Focus',maker:'Mindful',category:'Wellness',description:'A quieter mind, one conversation at a time.',price:'Free',rating:'4.9',color:'#e6ecec',ink:'#7f9b9a',type:3,label:'A MOMENT FOR YOURSELF.'},{id:'muse',name:'Muse',maker:'Studio North',category:'Creativity',description:'Turn passing thoughts into something good.',price:'$4 / mo',rating:'4.8',color:'#f0e7e0',ink:'#ae8c78',type:4,label:'FOLLOW YOUR CURIOSITY.'},{id:'compass',name:'Compass',maker:'AttentionAGI',category:'Everyday',description:'A helpful nudge for wherever life takes you.',price:'Free',rating:'4.7',color:'#e8eade',ink:'#8e9c68',type:5,label:'FIND YOUR NEXT STEP.'}];
let persisted={};try{persisted=JSON.parse(localStorage.getItem('pocket-workspace')||'{}')}catch{}
let state={page:'Marketplace',category:'All agents',search:'',sort:'popular',installed:(Array.isArray(persisted.installed)?persisted.installed:['notetaker','thinker']).filter((v,i,a)=>agents.some(x=>x.id===v)&&a.indexOf(v)===i),storage:persisted.storage||'AttentionAGI Cloud',retention:persisted.retention||'90 days',sync:persisted.sync??true,firmware:persisted.firmware||'1.4.2'};
const save=()=>{try{localStorage.setItem('pocket-workspace',JSON.stringify(state))}catch{toast('Browser storage is unavailable. Changes last for this session.')}};
function art(a){let shapes=['<path d="M26 28h42v45H26z" fill="none" stroke-width="2"/><path d="M34 21h42v45H34" fill="none" stroke-width="2"/><path d="M34 39h25M34 47h25M34 55h15" fill="none" stroke-width="2"/>','<g fill="none" stroke-width="1.4"><ellipse cx="50" cy="50" rx="28" ry="12"/><ellipse cx="50" cy="50" rx="28" ry="12" transform="rotate(60 50 50)"/><ellipse cx="50" cy="50" rx="28" ry="12" transform="rotate(120 50 50)"/><circle cx="50" cy="50" r="6"/></g>','<path d="M22 26h38v31H38L25 67V57h-3z" fill="none" stroke-width="1.5"/><path d="M44 42h34v30H65L53 80v-8h-9" fill="none" stroke-width="1.5"/><text x="31" y="48" stroke="none" font-size="19" font-family="serif">a</text><text x="54" y="65" stroke="none" font-size="16" font-family="serif">あ</text>','<g fill="none" stroke-width="1.2"><ellipse cx="50" cy="51" rx="30" ry="10"/><ellipse cx="50" cy="46" rx="24" ry="10"/><ellipse cx="50" cy="40" rx="17" ry="10"/><ellipse cx="50" cy="33" rx="10" ry="8"/><path d="M20 52v10c0 15 60 15 60 0V52"/></g>','<g fill="none" stroke-width="1.3"><path d="m50 17 8 20 21-8-8 21 17 9-22 7 2 20-18-13-17 13 1-22-23-5 20-11-8-20 21 8z"/><path d="m50 33 4 12 14-2-10 10 7 13-15-7-12 8 4-16-10-7 14 1z"/></g>','<g fill="none" stroke-width="1.4"><circle cx="50" cy="50" r="29"/><circle cx="50" cy="50" r="23"/><path d="m59 32-5 22-22 14 12-23z"/><path d="M50 17v7M50 76v7M17 50h7M76 50h7"/></g>'];return `<svg class="art" viewBox="0 0 100 100" stroke="${a.ink}" fill="${a.ink}" aria-hidden="true">${shapes[a.type]}</svg>`}
const heroArt=`<svg class="hero-art" viewBox="0 0 300 250" fill="none" aria-hidden="true"><defs><radialGradient id="orb"><stop stop-color="#f6f7ef"/><stop offset=".65" stop-color="#dce3cd"/><stop offset="1" stop-color="#abb995"/></radialGradient><pattern id="grain" width="5" height="5" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".5" fill="#7c8d65" opacity=".25"/></pattern></defs><g transform="translate(172 118) rotate(-27)"><ellipse rx="102" ry="58" stroke="#b6c2a1" stroke-width=".8"/><ellipse rx="119" ry="76" stroke="#c9d1bb" stroke-width=".7"/><ellipse rx="137" ry="93" stroke="#d5dbc9" stroke-width=".7"/><circle r="63" fill="url(#orb)"/><circle r="63" fill="url(#grain)"/><ellipse rx="102" ry="22" stroke="#8b9d73" stroke-width="1"/><ellipse rx="102" ry="58" stroke="#9cab86" stroke-width=".8" stroke-dasharray="0 175 240 300"/><circle cx="-96" cy="-19" r="5" fill="#879b6d"/><circle cx="101" cy="-56" r="3" fill="#9dad88"/></g><path d="m68 39 0 8m-4-4h8M247 190v10m-5-5h10" stroke="#9daa8a"/></svg>`;
let deviceSide='angle';
const device=()=>`<div class="device-preview"><div class="device-stage model-stage" data-viewer-state="loading"><model-viewer src="assets/attentionagi-device.glb" alt="Interactive 3D AttentionAGI device. Drag to rotate; scroll or pinch to zoom. Use arrow keys when focused." camera-controls disable-pan touch-action="pan-y" camera-orbit="${deviceSide==='front'?'0deg 90deg':deviceSide==='back'?'180deg 90deg':'-30deg 70deg'} auto" field-of-view="30deg" min-camera-orbit="auto 0deg 70%" max-camera-orbit="auto 180deg 180%" environment-image="neutral" exposure="1" shadow-intensity="0.3" interaction-prompt="none" loading="eager" tabindex="0"></model-viewer><img class="device-reference model-fallback" src="assets/device-${deviceSide==='back'?'back':'front'}.png" alt="AttentionAGI device ${deviceSide==='back'?'back':'front'} reference"><span class="model-status" role="status">Loading 3D device…</span></div><div class="device-views" role="group" aria-label="Device view"><button data-side="front" class="${deviceSide==='front'?'selected':''}" aria-pressed="${deviceSide==='front'}">Front</button><button data-side="back" class="${deviceSide==='back'?'selected':''}" aria-pressed="${deviceSide==='back'}">Back</button><button data-side="angle" class="${deviceSide==='angle'?'selected':''}" aria-pressed="${deviceSide==='angle'}">3D view</button></div><p class="model-hint">Drag to rotate · Scroll or pinch to zoom</p></div>`;
function card(a){return `<button class="agent-card" data-agent="${a.id}" aria-label="View ${a.name}"><div class="agent-art" style="background:${a.color}"><span class="art-label">${a.label}</span><span class="art-arrow">↗</span>${art(a)}</div><div class="agent-info"><div class="agent-title"><h3>${a.name}</h3><span class="rating">★ ${a.rating}</span></div><div class="maker">by ${a.maker} ${a.maker==='AttentionAGI'?'✧':''}</div><p>${a.description}</p><div class="card-footer"><span class="category">${a.category}</span><span class="price">${state.installed.includes(a.id)?'Added ✓':a.price}</span></div></div></button>`}
function panel(){return `<aside class="right-panel"><section class="panel device-panel"><div class="panel-header"><h2>Your pocket</h2><span class="status-pill"><span class="dot"></span>Demo device</span></div>${device()}<div class="device-name">AttentionAGI device <span>SILVER</span></div><div class="device-meta"><span>▰ 82% battery</span><span>◉ Wi-Fi connected</span></div><button class="outline-btn" data-page="Device">${icon('device')}Manage device${icon('arrow')}</button><div class="panel-line"><span>AttentionOS ${state.firmware}</span><b>${state.firmware==='1.5.0'?'Up to date':'Update available ↗'}</b></div></section><section class="panel"><div class="panel-header"><h2>On your pocket</h2><span style="font-size:8px;color:#929b86">${state.installed.length} agents</span></div><div class="installed-list">${state.installed.slice(0,3).map(id=>{const a=agents.find(a=>a.id===id);return `<div class="installed-item"><span class="mini-icon" style="background:${a.color}">${['▤','✺','あ','◎','✳','◇'][a.type]}</span><div>${a.name}<small>Ready when you are</small></div><span class="dot"></span></div>`}).join('')}</div><button class="text-link" data-page="My agents">View my agents <span>↗</span></button></section><section class="panel"><div class="panel-header"><h2>A home for your thoughts</h2>${icon('storage')}</div><div class="storage-label"><b>${state.storage}</b><span>2.4 of 10 GB</span></div><div class="progress"><div></div></div><div class="storage-note">Conversations, safely tucked away.</div><button class="text-link" data-page="Storage">Manage storage <span>↗</span></button></section></aside>`}
function marketplace(){return `<div class="body-grid"><div><section class="hero"><div class="tag">✧ &nbsp; SMALL DEVICE. BIG POSSIBILITIES.</div><h2>A good mind.<br>Always within reach.</h2><p>Meet the agents that make your everyday a little<br>easier. Find your people. In your pocket.</p><button class="black-btn" data-action="essentials">Explore the essentials ${icon('arrow')}</button>${heroArt}<div class="hero-dots"><i></i><i></i><i></i></div></section><div class="catalog-toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Find your next agent..." aria-label="Search agents" value="${escapeHTML(state.search)}"><kbd>/</kbd></label><div class="sort">Sort by <select id="sort" aria-label="Sort agents"><option value="popular">Most popular</option><option value="name">Name A–Z</option><option value="free">Free first</option></select></div></div><div class="filters">${['All agents','Productivity','Everyday','Learning','Wellness','Creativity'].map(c=>`<button data-category="${c}" class="${state.category===c?'active':''}">${c}</button>`).join('')}</div><div class="section-title"><h2>${state.category==='All agents'?'Find your everyday companions':state.category+' companions'}</h2><span id="result-count"></span></div><div class="agent-grid" id="agent-grid"></div><div class="catalog-bottom">${icon('shield')} Thoughtfully built. Carefully reviewed. Ready for your pocket.</div></div>${panel()}</div>`}
const conversations=[{title:'A better start to the week',agent:'Notetaker',date:'Today, 9:41 AM',duration:'12 min',summary:'A quiet planning session for the week ahead. Three priorities: finish the prototype, make time for a walk, and reconnect with the team.',transcript:'Let’s keep this week simple. The prototype is the first priority. I also want to protect a little time to get outside each day. Can you turn that into a short plan?'},{title:'That idea on the walk home',agent:'Thinker',date:'Yesterday, 5:23 PM',duration:'8 min',summary:'Explored an idea for a neighborhood book exchange. Start with one shelf, invite a few neighbors, and see what gets shared.',transcript:'What if we made a tiny book exchange for our building? Something that starts small, but gives people a reason to connect.'},{title:'Design sync & next steps',agent:'Notetaker',date:'Oct 11, 2:30 PM',duration:'24 min',summary:'Reviewed the device interaction. Keep the listening state visible, make agent switching quick, and prioritize readable type on the small screen.',transcript:'The screen should tell you at a glance what is happening. We need a clear listening indicator, and a simple way to move between agents.'}];
function otherPage(){if(state.page==='My agents')return `<div class="body-grid"><div><div class="section-title"><h2>Your everyday companions</h2><span>${state.installed.length} agents</span></div><div class="agent-grid">${agents.filter(a=>state.installed.includes(a.id)).map(card).join('')}</div><p class="demo-note">Your library is saved in this browser. Device sync will be available when a real device is connected.</p></div>${panel()}</div>`;if(state.page==='Conversations')return `<div class="body-grid"><div class="page-box"><div class="section-title"><h2>A little space to remember</h2><span>3 sample conversations</span></div>${conversations.map((c,i)=>`<button class="conversation-row" data-conversation="${i}"><span class="mini-icon">${i===1?'✺':'▤'}</span><div><strong>${c.title}</strong><small>${c.agent} · ${c.date}</small></div><span class="duration">${c.duration} ↗</span></button>`).join('')}<p class="demo-note">Sample conversations for exploring your workspace. Real recording and conversation hosting require a connected device and backend.</p></div>${panel()}</div>`;if(state.page==='Storage')return `<div class="body-grid"><div class="page-box"><div class="section-title"><h2>Your thoughts. Your choice.</h2>${icon('shield')}</div><div class="setting-row"><div><h3>Storage destination</h3><p>Choose where your conversations feel at home.</p></div><select id="storage" aria-label="Storage destination"><option>AttentionAGI Cloud</option><option>On-device only</option><option>Your own storage</option></select></div><div class="setting-row"><div><h3>Keep conversations for</h3><p>Automatically clear older conversations.</p></div><select id="retention" aria-label="Conversation retention"><option>30 days</option><option>90 days</option><option>1 year</option><option>Until I delete them</option></select></div><div class="setting-row"><div><h3>Automatic sync</h3><p>Sync when your pocket connects to Wi-Fi.</p></div><button class="switch ${state.sync?'':'off'}" role="switch" aria-checked="${state.sync}" aria-label="Automatic sync" data-action="sync"><i></i></button></div><div class="storage-label"><b>Demo storage usage</b><span>2.4 GB / 10 GB</span></div><div class="progress"><div></div></div><p class="demo-note">Preferences are saved locally. Cloud and personal storage connections are not yet connected.</p></div>${panel()}</div>`;return `<div class="body-grid"><div class="page-box"><div class="device-details">${device()}<div><span class="eyebrow">YOUR EVERYDAY COMPANION</span><h2>AttentionAGI device</h2><p>Silver · Demo device</p><p>AttentionOS ${state.firmware} · 82% battery</p><button class="outline-btn" data-action="pair">${icon('plus')}Connect a device</button></div></div><div class="setting-row"><div><h3>AttentionOS ${state.firmware==='1.5.0'?'1.5.0':'1.5.0 is here'}</h3><p>${state.firmware==='1.5.0'?'Your demo device is up to date.':'A clearer listening screen. A smoother everyday.'}</p></div><button class="black-btn" data-action="update">${state.firmware==='1.5.0'?'View release notes':'View update'} ${icon('arrow')}</button></div><div class="setting-row"><div><h3>Hold close. Start a conversation.</h3><p>Your pocket uses its microphone when you bring it close.</p></div>${icon('chat')}</div><p class="demo-note">This is a device management preview. Pairing and signed firmware delivery require the hardware API.</p></div>${panel()}</div>`}
const descriptions={Marketplace:['A little intelligence. A lot of possibility.','Discover agents that fit your life, and take them with you.'],'My agents':['Good company, wherever you go.','Your personal collection of everyday companions.'],Conversations:['Keep the thought going.','Your conversations, notes, and little moments of clarity.'],Storage:['Make room for what matters.','Choose a home for your conversations.'],Device:['A little closer to your pocket.','Keep your device connected and ready for your day.']};
function render(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#" aria-label="AttentionAGI home"><span class="brand-icon" aria-hidden="true">◎</span><span class="brand-name">Attention<span>AGI</span></span></a><div class="workspace"><span class="workspace-avatar">S</span><div>Personal workspace<small>A space of your own</small></div><span class="chevron">⌄</span></div><div class="nav-label">YOUR WORKSPACE</div><nav class="nav">${[['Marketplace','grid'],['My agents','box'],['Conversations','chat'],['Storage','storage'],['Device','device']].map(([p,i])=>`<button data-page="${p}" class="${state.page===p?'active':''}">${icon(i)}${p}${p==='My agents'?`<span class="count">${state.installed.length}</span>`:''}${p==='Device'?'<span class="dot" style="margin-left:auto"></span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="help-card"><b>A little help getting started?</b><p>Your pocket can do a lot.<br>Let’s find your first little thing.</p><button data-action="guide">Meet your pocket <span>↗</span></button></div><div class="profile"><span class="avatar">SK</span><div>Sanjay Kumaran<small>Personal account</small></div><button data-action="profile" aria-label="Account settings" style="margin-left:auto">${icon('settings')}</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace<span>/</span><b>${state.page}</b></div><div class="top-actions"><span class="online"><span class="dot"></span>All systems operational</span><button data-action="notifications" aria-label="Notifications">${icon('bell')}</button><span class="avatar" style="width:25px;height:25px;font-size:8px">SK</span></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">${state.page==='Marketplace'?'THE ATTENTIONAGI MARKETPLACE':'YOUR ATTENTIONAGI WORKSPACE'}</div><h1>${state.page==='Marketplace'?'Good company for your pocket.':descriptions[state.page][0]}</h1><p>${descriptions[state.page][1]}</p></div>${state.page==='Marketplace'?`<button class="outline-btn" data-action="build">${icon('plus')}Build an agent ${icon('external')}</button>`:''}</div>${state.page==='Marketplace'?marketplace():otherPage()}<footer class="footer"><span>A little technology. A more human day.</span><div><button data-action="privacy">Privacy first</button><button data-action="help">Help & support ↗</button><span>© 2026 AttentionAGI</span></div></footer></div></main></div>`;if(state.page==='Marketplace'){document.getElementById('sort').value=state.sort;renderCards();document.getElementById('search').addEventListener('input',e=>{state.search=e.target.value;renderCards()});document.getElementById('sort').onchange=e=>{state.sort=e.target.value;renderCards()}}if(state.page==='Storage'){for(const key of ['storage','retention']){document.getElementById(key).value=state[key];document.getElementById(key).onchange=e=>{state[key]=e.target.value;save();toast('Preference saved');render()}}}}
function renderCards(){let list=agents.filter(a=>(state.category==='All agents'||a.category===state.category)&&(a.name+' '+a.description+' '+a.category).toLowerCase().includes(state.search.toLowerCase()));if(state.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));if(state.sort==='free')list.sort((a,b)=>(a.price!=='Free')-(b.price!=='Free'));document.getElementById('agent-grid').innerHTML=list.length?list.map(card).join(''):'<div class="empty" style="grid-column:1/-1">No agents found. Try another name or category.</div>';document.getElementById('result-count').textContent=`${list.length} thoughtfully selected agent${list.length===1?'':'s'}`}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}function modal(content){const d=document.getElementById('modal');d.innerHTML='<button class="modal-close" aria-label="Close dialog">×</button>'+content;d.querySelector('.modal-close').onclick=()=>d.close();if(!d.open)d.showModal()}function agentModal(id){const a=agents.find(a=>a.id===id);const added=state.installed.includes(id);modal(`<div class="modal-art" style="background:${a.color}">${art(a)}</div><div class="eyebrow">${a.category} · ★ ${a.rating}</div><h2>${a.name}</h2><p>${a.description} Built by ${a.maker} for the moments that matter.</p><ul><li>Made for natural, voice-first conversations</li><li>Works with your conversation storage preferences</li><li>Ready to join your personal agent library</li></ul><button class="black-btn" data-install="${id}">${added?'Remove from my agents':a.price==='Free'?'Add to my pocket — Free':'Try in demo — '+a.price}</button><p class="demo-note">Demo library only. No charge or device installation occurs.</p>`)}
document.addEventListener('click',e=>{const side=e.target.closest('[data-side]');if(side){deviceSide=side.dataset.side;document.querySelectorAll('model-viewer').forEach(v=>v.setAttribute('camera-orbit',deviceSide==='front'?'0deg 90deg auto':deviceSide==='back'?'180deg 90deg auto':'-30deg 70deg auto'));document.querySelectorAll('[data-side]').forEach(b=>{const selected=b.dataset.side===deviceSide;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});document.querySelectorAll('.model-fallback').forEach(img=>{img.src='assets/device-'+(deviceSide==='back'?'back':'front')+'.png';img.alt='AttentionAGI device '+(deviceSide==='back'?'back':'front')+' reference'});return}const p=e.target.closest('[data-page]');if(p){state.page=p.dataset.page;render();window.scrollTo(0,0);return}const c=e.target.closest('[data-category]');if(c){state.category=c.dataset.category;render();return}const a=e.target.closest('[data-agent]');if(a){agentModal(a.dataset.agent);return}const install=e.target.closest('[data-install]');if(install){const id=install.dataset.install,had=state.installed.includes(id);state.installed=had?state.installed.filter(x=>x!==id):[...state.installed,id];save();document.getElementById('modal').close();render();toast(had?'Agent removed from your library':'A new companion, added to your library.');return}const conv=e.target.closest('[data-conversation]');if(conv){const c=conversations[+conv.dataset.conversation];modal(`<div class="eyebrow">SAMPLE CONVERSATION · ${c.duration}</div><h2>${c.title}</h2><p>${c.agent} · ${c.date}</p><div class="transcript"><b>THE TAKEAWAY</b>${c.summary}</div><div class="transcript"><b>TRANSCRIPT EXCERPT</b>“${c.transcript}”</div><button class="black-btn" data-export="${conv.dataset.conversation}">Export conversation ${icon('arrow')}</button>`);return}const exp=e.target.closest('[data-export]');if(exp){const c=conversations[+exp.dataset.export];const blob=new Blob([`${c.title}\n${c.agent} · ${c.date}\n\nSUMMARY\n${c.summary}\n\nTRANSCRIPT\n${c.transcript}`],{type:'text/plain'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=c.title.toLowerCase().replaceAll(' ','-')+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='essentials'){state.category='All agents';state.search='';render();document.querySelector('.catalog-toolbar').scrollIntoView({behavior:'smooth',block:'start'});toast('Start with Notetaker, Thinker, and Compass — the AttentionAGI essentials.')}if(action==='sync'){state.sync=!state.sync;save();render();toast('Sync preference saved')}if(action==='notifications')modal('<div class="eyebrow">YOUR UPDATES</div><h2>A little something new.</h2><p>AttentionOS 1.5.0 is ready to explore in the device preview.</p><button class="black-btn" data-action="goto-device">View device update →</button>');if(action==='goto-device'){document.getElementById('modal').close();state.page='Device';render()}if(action==='update')modal(`<div class="eyebrow">POCKET OS · RELEASE NOTES</div><h2>A smoother everyday.</h2><p>Version 1.5.0 brings thoughtful improvements to your pocket.</p><ul><li>A clearer listening indicator</li><li>Faster switching between agents</li><li>Improved Wi-Fi reconnect behavior</li></ul><p class="demo-note">This previews the update flow. No firmware will be sent to hardware.</p><button class="black-btn" data-action="apply-update">${state.firmware==='1.5.0'?'Preview again':'Preview update'}</button>`);if(action==='apply-update'){state.firmware='1.5.0';save();document.getElementById('modal').close();render();toast('Update preview complete. Demo device is on AttentionOS 1.5.0.')}if(action==='pair')modal('<div class="eyebrow">CONNECT YOUR POCKET</div><h2>Let’s get acquainted.</h2><p>On your AttentionAGI, open Settings → Connect and find your six-digit pairing code.</p><form id="pair-form"><label>Device pairing code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required></label><button class="black-btn" type="submit">Check pairing code →</button></form><p class="demo-note">Hardware pairing is not connected in this prototype.</p>');if(action==='build')modal('<div class="eyebrow">FOR THE BUILDERS</div><h2>A little idea. A new agent.</h2><p>Draft an agent for AttentionAGI. Give it a name and a clear purpose to start.</p><form id="build-form"><label>Agent name<input name="name" maxlength="40" placeholder="e.g. Trail guide" required></label><label>What does it help with?<input name="purpose" maxlength="200" placeholder="A companion for the path less traveled" required></label><button class="black-btn" type="submit">Download agent draft →</button></form><p class="demo-note">Download a starter specification. Publishing and agent runtime integration are coming next.</p>');if(['guide','help'].includes(action))modal('<div class="eyebrow">MEET YOUR POCKET</div><h2>A little help, always close.</h2><ul><li>Discover a companion in the marketplace.</li><li>Add it to your personal agent library.</li><li>Connect your device and hold it close to speak.</li><li>Revisit your thoughts in Conversations.</li><li>Choose where they’re stored in Storage.</li></ul><p>This interactive prototype saves your preferences in this browser. Device, AI runtime, and cloud services are the next integration step.</p>');if(action==='privacy')modal('<div class="eyebrow">YOUR POCKET, YOUR CHOICE</div><h2>Room for private thoughts.</h2><p>This prototype stores only library and settings preferences in your browser. It does not access your microphone or upload conversations.</p><p>The storage workspace lets you explore device-only storage, cloud storage, and retention settings before real services are connected.</p>');if(action==='profile')modal('<div class="eyebrow">PERSONAL WORKSPACE</div><h2>Sanjay’s AttentionAGI.</h2><p>Your personal demo workspace. Agent choices and storage preferences stay in this browser.</p><button class="black-btn" data-action="reset">Reset demo preferences</button>');if(action==='reset'){localStorage.removeItem('pocket-workspace');location.reload()}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='pair-form')toast('Code format checked. Connect the hardware API to finish pairing.');if(e.target.id==='build-form'){const data=new FormData(e.target);const spec={name:data.get('name'),description:data.get('purpose'),version:'0.1.0',interface:'voice',permissions:['microphone'],status:'draft'};const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(spec,null,2)],{type:'application/json'}));link.download='attentionagi-agent-draft.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Your agent draft is ready.');document.getElementById('modal').close()}});document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.getElementById('modal').open){e.preventDefault();document.getElementById('search')?.focus()}});render();
